// D:/Sync/sketch_aug19a/test_01/test_01.ino
#include <Arduino.h>
#include <driver/i2s.h>

#define I2S_SD          15
#define I2S_WS          17
#define I2S_SCK         16
#define I2S_PORT        I2S_NUM_0
#define SAMPLE_RATE     16000
#define BUFFER_SIZE     512

int32_t raw_samples[BUFFER_SIZE];
int16_t pcm_samples[BUFFER_SIZE];

void setup_i2s() {
  const i2s_config_t i2s_config = {
    .mode = (i2s_mode_t)(I2S_MODE_MASTER | I2S_MODE_RX),
    .sample_rate = SAMPLE_RATE,
    .bits_per_sample = I2S_BITS_PER_SAMPLE_32BIT,
    .channel_format = I2S_CHANNEL_FMT_ONLY_LEFT,
    .communication_format = i2s_comm_format_t(I2S_COMM_FORMAT_STAND_I2S),
    .intr_alloc_flags = ESP_INTR_FLAG_LEVEL1,
    .dma_buf_count = 4,
    .dma_buf_len = BUFFER_SIZE,
    .use_apll = false,
    .tx_desc_auto_clear = false,
    .fixed_mclk = 0
  };

  const i2s_pin_config_t pin_config = {
    .bck_io_num = I2S_SCK,
    .ws_io_num = I2S_WS,
    .data_out_num = I2S_PIN_NO_CHANGE,
    .data_in_num = I2S_SD
  };

  esp_err_t err = i2s_driver_install(I2S_PORT, &i2s_config, 0, NULL);
  if (err != ESP_OK) {
    while (true);
  }

  err = i2s_set_pin(I2S_PORT, &pin_config);
  if (err != ESP_OK) {
    while (true);
  }
}

void setup() {
  Serial.begin(921600);
  while (!Serial);

  setup_i2s();
  i2s_start(I2S_PORT);
}

void loop() {
  size_t bytes_read = 0;
  esp_err_t result = i2s_read(I2S_PORT, &raw_samples, sizeof(raw_samples), &bytes_read, portMAX_DELAY);

  if (result == ESP_OK && bytes_read > 0) {
    int samples_count = bytes_read / sizeof(int32_t);
    for (int i = 0; i < samples_count; i++) {
      pcm_samples[i] = (int16_t)(raw_samples[i] >> 14);
    }
    Serial.write((uint8_t *)pcm_samples, samples_count * sizeof(int16_t));
  }
}

